function Contact() {
  return (
    <section id="contact" className="contact">
      <div className="container">

        <h2>Contact Me</h2>

        <input placeholder="Your Name" />
        <input placeholder="Email" />
        <textarea placeholder="Message"></textarea>

      </div>
    </section>
  );
}

export default Contact;
